insert into plm_material_group (
    group_key,
    group_code,
    group_name,
    group_level,
    display_name,
    normalized_display_name,
    ecount_major_code,
    ecount_major_name,
    ecount_minor_code,
    ecount_minor_name,
    inventory_type,
    warning_flag,
    warning_message,
    source_record_count,
    sort_order,
    source_system,
    status,
    created_by,
    updated_by,
    deleted_flag
)
select
    seed.group_key,
    seed.group_code,
    seed.group_name,
    seed.group_level,
    seed.display_name,
    seed.normalized_display_name,
    seed.ecount_major_code,
    seed.ecount_major_name,
    seed.ecount_minor_code,
    seed.ecount_minor_name,
    seed.inventory_type,
    seed.warning_flag,
    seed.warning_message,
    seed.source_record_count,
    seed.sort_order,
    'ECOUNT',
    'active',
    'system',
    'system',
    0
from seed
where not exists (
    select 1
    from plm_material_group existing
    where existing.source_system = 'ECOUNT'
      and existing.group_key = seed.group_key
      and existing.deleted_flag = 0
);

